    for _, num := range nums {
        if num > l {
            l = num
        }
        r += num
    }
    res := r

    for l <= r {
        mid := l + (r-l)/2
        if canSplit(mid) {
            res = mid
            r = mid - 1
        } else {
            l = mid + 1
        }
    }
    return res
}
